// src/modules/groupes/utils/return-group-data.ts
export function returnGroupData(
  data: any,
  message = 'Success',
  meta: Record<string, any> = {},
) {
  const isArray = Array.isArray(data);
  const timestamp = new Date().toISOString();

  if (isArray) {
    return {
      success: true,
      message,
      count: data.length,
      timestamp,
      groupes: data,
      ...meta,
    };
  }

  return {
    success: true,
    message,
    timestamp,
    group: data,
    ...meta,
  };
}
